   // The core issue: each '?' can satisfy either the literal `?` in the inner group 
   // or the trailing `[\\x21-\\x7E]*`. This ambiguity forces the engine to explore 
   // all possible ways to partition the overlapping characters, resulting in O(2^n) complexity.
   const separatorCount = 1800;
   const ambiguousSuffix = Array(separatorCount).fill('?').join('');

