   // This guarantees the `$` anchor will fail, forcing the engine to backtrack through 
   // EVERY possible partition combination rather than failing-fast at the mismatch point.
   const craftedSRI = `sha256-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA==${ambiguousSuffix}\r`;

